use vstd::prelude::*;

verus! {

fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
    ensures
        b@ == a@,
        b.len() == a.len(),
{
    let mut b: Vec<u64> = Vec::with_capacity(a.len());

    for &x in a.iter()
        invariant
            // The constructed prefix matches the corresponding prefix of `a`
            b@ == a@.subrange(0, b.len() as int),
            b.len() <= a.len(),
        ensures
            b@ == a@,
            b.len() == a.len(),
    {
        b.push(x);

        // Help the prover connect the element obtained from the iterator to the
        // next element in `a`'s sequence.
        assert(b@.drop_last() == a@.subrange(0, (b.len() as int) - 1));
        assert(b@.last() == a@[b.len() - 1]);
    }

    b
}

}

